def hist_k(p, k, E1, n, dl):
    """h[d] = sum of chi2(y_P) over P in E(F_{p^k}) with Tr_{k/1}(P) = [d]G."""
    q = p ** k
    Fq = GF(q, 'g')
    Eq = EllipticCurve(Fq, [_sage_const_0 , Fq(B)])
    h = [_sage_const_0 ] * n
    half = (q - _sage_const_1 ) // _sage_const_2 
